import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"83. 内联组装和硬件访问","description":"The Little Book of C 中文版 — 83. 内联组装和硬件访问","frontmatter":{"title":"83. 内联组装和硬件访问","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 83. 内联组装和硬件访问","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":83,"sidebarWeight":83,"alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/083-Inline Assembly and Hardware Access","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/083-Inline Assembly and Hardware Access"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/083-Inline Assembly and Hardware Access.md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/083-Inline Assembly and Hardware Access.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/09-可移植与现代 C/083-Inline Assembly and Hardware Access.md"};function o(l,a,i,d,c,u){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/083-Inline Assembly and Hardware Access)</p><p>C 可以让您精确控制内存和性能，但有时您需要更深入一层，直接控制 CPU。这就是内联汇编的用武之地：将汇编语言嵌入到 C 代码中以优化性能或访问硬件级功能。</p><p>本章将展示如何安全、可移植且有意义地混合 C 和汇编。</p><h4 id="步骤-1-什么是内联汇编" tabindex="-1">步骤 1. 什么是内联汇编？ <a class="header-anchor" href="#步骤-1-什么是内联汇编" aria-label="Permalink to &quot;步骤 1. 什么是内联汇编？&quot;">​</a></h4><p>内联汇编允许您将机器指令的小片段插入到 C 程序中。您可以用它来：</p><ul><li>访问 C 未公开的 CPU 指令。</li><li>优化性能关键路径。</li><li>实施硬件驱动程序或低级例程。</li></ul><p>然而，它也是不可移植的并且是特定于编译器的，因此请谨慎使用它并将其隔离在干净的 C 接口后面。</p><h4 id="步骤-2-两种常见口味" tabindex="-1">步骤 2. 两种常见口味 <a class="header-anchor" href="#步骤-2-两种常见口味" aria-label="Permalink to &quot;步骤 2. 两种常见口味&quot;">​</a></h4><p>GCC / Clang 语法（AT&amp;T 或 Intel 风格）使用<code>asm</code>或者<code>__asm__</code>关键词。</p><p>MSVC 语法用途<code>__asm { ... }</code>内部函数。</p><p>我们将重点关注 GCC/Clang 语法，因为它在大多数系统编程环境中使用。</p><h4 id="步骤-3-基本内联汇编示例" tabindex="-1">步骤 3. 基本内联汇编示例 <a class="header-anchor" href="#步骤-3-基本内联汇编示例" aria-label="Permalink to &quot;步骤 3. 基本内联汇编示例&quot;">​</a></h4><p>Tiny Code：打印 CPU ID 寄存器（仅限 x86）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    unsigned int eax, ebx, ecx, edx;</span></span>
<span class="line"><span>    eax = 0;</span></span>
<span class="line"><span>    __asm__ __volatile__(</span></span>
<span class="line"><span>        &quot;cpuid&quot;</span></span>
<span class="line"><span>        : &quot;=a&quot;(eax), &quot;=b&quot;(ebx), &quot;=c&quot;(ecx), &quot;=d&quot;(edx)</span></span>
<span class="line"><span>        : &quot;a&quot;(0)</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>    printf(&quot;CPU Vendor: %.4s%.4s%.4s\\n&quot;,</span></span>
<span class="line"><span>           (char*)&amp;ebx, (char*)&amp;edx, (char*)&amp;ecx);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>解释：</p><p>-<code>cpuid</code>是一条向寄存器填充信息的CPU指令。 -<code>&quot;=a&quot;(eax)</code>意思是“存储寄存器的输出<code>eax</code>进入变量<code>eax</code>.” -<code>: &quot;a&quot;(0)</code>意思是“将 0 放入<code>eax</code>在运行指令之前。”</p><ul><li>这<code>__volatile__</code>关键字告诉编译器不要优化它。</li></ul><h4 id="步骤-4-gcc-内联汇编语法" tabindex="-1">步骤 4.GCC 内联汇编语法 <a class="header-anchor" href="#步骤-4-gcc-内联汇编语法" aria-label="Permalink to &quot;步骤 4.GCC 内联汇编语法&quot;">​</a></h4><p>一般形式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asm volatile (&quot;instruction list&quot;</span></span>
<span class="line"><span>              : output_operands</span></span>
<span class="line"><span>              : input_operands</span></span>
<span class="line"><span>              : clobbered_registers);</span></span></code></pre></div><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asm volatile (&quot;addl %%ebx, %%eax&quot;</span></span>
<span class="line"><span>              : &quot;=a&quot;(result)</span></span>
<span class="line"><span>              : &quot;a&quot;(x), &quot;b&quot;(y));</span></span></code></pre></div><p>解释：</p><p>-<code>&quot;addl %%ebx, %%eax&quot;</code>, 装配说明 -<code>&quot;=a&quot;(result)</code>，输出于<code>eax</code>去<code>result</code> -<code>&quot;a&quot;(x), &quot;b&quot;(y)</code>，输入：放<code>x</code>在<code>eax</code>,<code>y</code>在<code>ebx</code></p><h4 id="步骤-5-读取-cpu-周期计数器" tabindex="-1">步骤 5. 读取 CPU 周期计数器 <a class="header-anchor" href="#步骤-5-读取-cpu-周期计数器" aria-label="Permalink to &quot;步骤 5. 读取 CPU 周期计数器&quot;">​</a></h4><p>Tiny Code：测量操作之间的 CPU 周期</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>unsigned long long rdtsc(void) {</span></span>
<span class="line"><span>    unsigned int lo, hi;</span></span>
<span class="line"><span>    __asm__ __volatile__(&quot;rdtsc&quot; : &quot;=a&quot;(lo), &quot;=d&quot;(hi));</span></span>
<span class="line"><span>    return ((unsigned long long)hi &lt;&lt; 32) | lo;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    unsigned long long start = rdtsc();</span></span>
<span class="line"><span>    for (volatile int i = 0; i &lt; 1000000; i++);</span></span>
<span class="line"><span>    unsigned long long end = rdtsc();</span></span>
<span class="line"><span>    printf(&quot;Cycles: %llu\\n&quot;, end - start);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>解释：</p><p>-<code>rdtsc</code>读取 CPU 的时间戳计数器。</p><ul><li>它是 CPU 周期时间的精确测量，非常适合微基准测试。</li></ul><h4 id="步骤-6-写入-i-o-端口-嵌入式或内核上下文" tabindex="-1">步骤 6. 写入 I/O 端口（嵌入式或内核上下文） <a class="header-anchor" href="#步骤-6-写入-i-o-端口-嵌入式或内核上下文" aria-label="Permalink to &quot;步骤 6. 写入 I/O 端口（嵌入式或内核上下文）&quot;">​</a></h4><p>如果您正在编写嵌入式代码或操作系统内核，您通常会直接与硬件寄存器交互。</p><p>示例（x86，仅限特权模式）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static inline void outb(unsigned short port, unsigned char value) {</span></span>
<span class="line"><span>    __asm__ __volatile__(&quot;outb %0, %1&quot; : : &quot;a&quot;(value), &quot;Nd&quot;(port));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这会将一个字节写入 I/O 端口，用于串行端口、定时器或 PIC 控制器等设备。</p><p>在用户空间中，您通常无法执行此操作（需要内核权限）。</p><h4 id="步骤-7-内存屏障和-cpu-围栏" tabindex="-1">步骤 7. 内存屏障和 CPU 围栏 <a class="header-anchor" href="#步骤-7-内存屏障和-cpu-围栏" aria-label="Permalink to &quot;步骤 7. 内存屏障和 CPU 围栏&quot;">​</a></h4><p>使用并发或硬件时，您可能需要控制指令顺序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__asm__ __volatile__(&quot;mfence&quot; ::: &quot;memory&quot;);</span></span></code></pre></div><p>这告诉 CPU 和编译器不要重新排序内存操作，这对于在硬件级别编写线程安全或设备控制代码至关重要。</p><h4 id="步骤-8-注册约束" tabindex="-1">步骤 8. 注册约束 <a class="header-anchor" href="#步骤-8-注册约束" aria-label="Permalink to &quot;步骤 8. 注册约束&quot;">​</a></h4><p>GCC 允许您指定要使用的寄存器。</p><table tabindex="0"><thead><tr><th>约束</th><th>注册</th><th>意义</th></tr></thead><tbody><tr><td><code>&quot;a&quot;</code></td><td><code>eax</code></td><td>蓄能器</td></tr><tr><td><code>&quot;b&quot;</code></td><td><code>ebx</code></td><td>基地</td></tr><tr><td><code>&quot;c&quot;</code></td><td><code>ecx</code></td><td>柜台</td></tr><tr><td><code>&quot;d&quot;</code></td><td><code>edx</code></td><td>数据</td></tr><tr><td><code>&quot;S&quot;</code></td><td><code>esi</code></td><td>来源索引</td></tr><tr><td><code>&quot;D&quot;</code></td><td><code>edi</code></td><td>目的地索引</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asm(&quot;mul %1&quot; : &quot;=a&quot;(res) : &quot;r&quot;(x));</span></span></code></pre></div><p>这<code>&quot;r&quot;</code>约束允许编译器选择任何寄存器。</p><h4 id="步骤-9-混合汇编和-c-函数" tabindex="-1">步骤 9. 混合汇编和 C 函数 <a class="header-anchor" href="#步骤-9-混合汇编和-c-函数" aria-label="Permalink to &quot;步骤 9. 混合汇编和 C 函数&quot;">​</a></h4><p>您可以单独编写小例程<code>.S</code>文件（纯汇编）并从 C: 调用它们</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># file: add.S</span></span>
<span class="line"><span>.global add_two</span></span>
<span class="line"><span>add_two:</span></span>
<span class="line"><span>    addl %esi, %edi</span></span>
<span class="line"><span>    movl %edi, %eax</span></span>
<span class="line"><span>    ret</span></span></code></pre></div><p>然后在C中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add_two(int a, int b);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add_two(5, 7));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这种混合风格用于操作系统内核、引导加载程序和数学库。</p><h4 id="步骤-10-小代码-内联汇编添加函数" tabindex="-1">步骤 10. 小代码：内联汇编添加函数 <a class="header-anchor" href="#步骤-10-小代码-内联汇编添加函数" aria-label="Permalink to &quot;步骤 10. 小代码：内联汇编添加函数&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add_fast(int a, int b) {</span></span>
<span class="line"><span>    int result;</span></span>
<span class="line"><span>    __asm__ (&quot;addl %1, %0&quot; : &quot;=r&quot;(result) : &quot;r&quot;(b), &quot;0&quot;(a));</span></span>
<span class="line"><span>    return result;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add_fast(3, 5));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这<code>&quot;0&quot;(a)</code>约束告诉编译器使用相同的寄存器进行输入和输出。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>内联汇编会告诉您 C 代码下面到底发生了什么。即使您很少使用它，了解它也可以帮助您：</p><ul><li>读取编译器生成的程序集（<code>gcc -S</code>)</li><li>优化性能关键代码</li><li>了解系统调用、上下文切换和内核陷阱如何工作</li></ul><p>这是软件与硬件相遇的地方，硬件是计算的真正金属。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个小的内联汇编片段来交换两个整数。</li><li>打印 CPU 供应商字符串<code>cpuid</code>.</li><li>使用<code>rdtsc()</code>对您的功能进行基准测试。</li><li>使用检查编译器生成的程序集<code>gcc -S</code>.</li><li>尝试在汇编中重新实现基本数学运算并比较性能。</li></ol><p>接下来，您将学习交叉编译，即如何在您自己的机器上为其他架构和系统构建 C 程序。</p>`,62)])])}const b=s(p,[["render",o]]);export{h as __pageData,b as default};
